window.__finlexDocLoaded(10172,{"id":10172,"articles":[{"id":1000719,"no":"Overview","heading":"Scope & Statutory / Regulatory Role (Public Summary)","text":"Addresses the auditor's responsibility to plan and perform the audit to obtain reasonable assurance about whether the financial statements are free of material misstatement caused by fraudulent financial reporting or misappropriation of assets.","seq":0},{"id":1000720,"no":"AS 2401.52–.67","heading":"Management Override of Controls, Journal Entry Testing & Estimates","text":"• Mandatory Procedures for Management Override (AS 2401.57–.67):\n  1. Examine journal entries and other adjustments for evidence of possible material misstatement due to fraud.\n  2. Review accounting estimates for management bias (including retrospective review of prior-year estimates).\n  3. Evaluate the business purpose (or lack thereof) for significant unusual transactions.\n• Unpredictability: Incorporate an element of unpredictability in selecting audit procedures.","seq":1},{"id":1000721,"no":"Cross-Framework Comparison","heading":"US vs. International (ISA/OECD/COSO) & China Context","text":"• Closely aligned with ISA 240 (Revised) and China's CSA 1141 on the three mandatory management-override procedures.","seq":2},{"id":1000722,"no":"Official Access","heading":"Official Regulatory / Statutory Source","text":"Official Source (PCAOB Auditing Standards): https://pcaobus.org/oversight/standards/auditing-standards\nStatus: in_force.","seq":3}]});
